pub const CudaContext = struct {
    device: c_int,
    context: cuda.CUcontext,
    stream: cuda.CUstream,
    allocator: Allocator,

    pub fn init(allocator: Allocator, device_id: c_int) !CudaContext {
        try checkCudaError(cuda.cuInit(0));
        var dev: cuda.CUdevice = undefined;
        try checkCudaError(cuda.cuDeviceGet(&dev, device_id));

        var ctx: cuda.CUcontext = undefined;
        try checkCudaError(cuda.cuCtxCreate(&ctx, 0, dev));

        var stream: cuda.CUstream = undefined;
        try checkCudaError(cuda.cuStreamCreate(&stream, 0));

        return .{
            .device = device_id,
            .context = ctx,
            .stream = stream,
            .allocator = allocator,
        };
    }

    pub fn launchKernel(
        self: *CudaContext,
        kernel: cuda.CUfunction,
        grid: [3]u32,
        block: [3]u32,
        args: []const *anyopaque
    ) !void {
        try checkCudaError(cuda.cuLaunchKernel(
            kernel,
            grid[0], grid[1], grid[2],
            block[0], block[1], block[2],
            0,  // shared memory
            self.stream,
            @ptrCast(args.ptr),
            null
        ));
        try checkCudaError(cuda.cuStreamSynchronize(self.stream));
    }
};


Memory Management:
zig
pub const CudaBuffer = struct {
    ptr: cuda.CUdeviceptr,
    size: usize,
    context: *CudaContext,

    pub fn allocate(ctx: *CudaContext, size: usize) !CudaBuffer {
        var ptr: cuda.CUdeviceptr = undefined;
        try checkCudaError(cuda.cuMemAlloc(&ptr, size));
        return .{ .ptr = ptr, .size = size, .context = ctx };
    }

    pub fn copyToDevice(self: *CudaBuffer, host_data: []const u8) !void {
        if (host_data.len > self.size) return error.BufferTooSmall;
        try checkCudaError(cuda.cuMemcpyHtoD(
            self.ptr,
            host_data.ptr,
            host_data.len
        ));
    }

    pub fn copyFromDevice(self: *CudaBuffer, host_buffer: []u8) !void {
        if (host_buffer.len < self.size) return error.BufferTooSmall;
        try checkCudaError(cuda.cuMemcpyDtoH(
            host_buffer.ptr,
            self.ptr,
            self.size
        ));
    }
};


Tensor Kernels:
zig
// Matrix multiplication kernel dispatch
pub fn matmulCuda(
    ctx: *CudaContext,
    a: *const Tensor,
    b: *const Tensor,
    c: *Tensor
) !void {
    const m = a.shape.dims[0];
    const n = b.shape.dims[1];
    const k = a.shape.dims[1];

    // Allocate device buffers
    var d_a = try CudaBuffer.allocate(ctx, a.data.len * @sizeOf(f32));
    defer d_a.free();
    var d_b = try CudaBuffer.allocate(ctx, b.data.len * @sizeOf(f32));
    defer d_b.free();
    var d_c = try CudaBuffer.allocate(ctx, c.data.len * @sizeOf(f32));
    defer d_c.free();

    // Copy to device
    try d_a.copyToDevice(std.mem.sliceAsBytes(a.data));
    try d_b.copyToDevice(std.mem.sliceAsBytes(b.data));

    // Launch kernel
    const block_size: u32 = 16;
    const grid_x = (n + block_size - 1) / block_size;
    const grid_y = (m + block_size - 1) / block_size;

    const args: []const *anyopaque = &[_]*const anyopaque{
        &d_a.ptr, &d_b.ptr, &d_c.ptr, &m, &n, &k
    };

    try ctx.launchKernel(
        matmul_kernel,
        .{grid_x, grid_y, 1},
        .{block_size, block_size, 1},
        args
    );

    // Copy result back
    try d_c.copyFromDevice(std.mem.sliceAsBytes(c.data));
}




