pub fn matmulFuthark(
    ctx: *FutharkContext,
    a: *const Tensor,
    b: *const Tensor
) !Tensor {
    // Create Futhark arrays
    const a_dims = [2]i64{ @intCast(a.shape.dims[0]), @intCast(a.shape.dims[1]) };
    var f_a = futhark.futhark_new_f32_2d(
        ctx.context,
        a.data.ptr,
        a_dims[0],
        a_dims[1]
    ) orelse return error.AllocationFailed;
    defer futhark.futhark_free_f32_2d(ctx.context, f_a);

    const b_dims = [2]i64{ @intCast(b.shape.dims[0]), @intCast(b.shape.dims[1]) };
    var f_b = futhark.futhark_new_f32_2d(
        ctx.context,
        b.data.ptr,
        b_dims[0],
        b_dims[1]
    ) orelse return error.AllocationFailed;
    defer futhark.futhark_free_f32_2d(ctx.context, f_b);

    // Call Futhark function
    var f_c: *futhark.futhark_f32_2d = undefined;
    const ret = futhark.futhark_entry_matmul(ctx.context, &f_c, f_a, f_b);
    if (ret != 0) return error.KernelFailed;
    defer futhark.futhark_free_f32_2d(ctx.context, f_c);

    // Extract result
    const result_dims = [2]usize{
        @intCast(futhark.futhark_shape_f32_2d(ctx.context, f_c)[0]),
        @intCast(futhark.futhark_shape_f32_2d(ctx.context, f_c)[1]),
    };

    var result = try Tensor.init(a.allocator, &result_dims);
    const values = futhark.futhark_values_f32_2d(ctx.context, f_c);
    @memcpy(result.data, values[0 .. result.data.len]);

    return result;
}


